const AUTHORED_ERRORS = new Set([
    "JWT header and claims must be JSON objects",
    "JWT must have exactly 3 parts separated by '.'", "Invalid JWT", "Invalid JSON in header or payload",
    "Invalid JWS format - must have 3 parts", "Public key is required for asymmetric algorithms", "Signature verification failed",
    "Invalid JWE format - must have 5 parts", "Private key is required for RSA decryption", "Decryption key is required",
]);
export function localizeJoseError(t: (source: string, values?: Record<string, string | number>) => string, diagnostic: string): string {
    if (AUTHORED_ERRORS.has(diagnostic)) return t(diagnostic);
    if (diagnostic.startsWith("Unsupported algorithm: ")) return t("Unsupported algorithm: {algorithm}", { algorithm: diagnostic.slice("Unsupported algorithm: ".length) });
    for (const [prefix, recovery] of [
        ["Verification failed: ", "Verification failed. Check the token and trusted verification key, then try again."],
        ["Decryption failed: ", "Decryption failed. Check the token, algorithm and key, then try again."],
    ]) if (diagnostic.startsWith(prefix)) return t(recovery) + "\n" + diagnostic.slice(prefix.length);
    return diagnostic;
}
